INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('奔跑吧', 14, 2, '第2期·24K风暴Ⅱ（商战剧本杀）', '2026-05-01', '[{"name": "人体斯坦尼康", "play_style": "words", "rules": "1. 每组轮流上场，一人当『摄像机』举着手机拍摄。\n2. 其余队员用头顶、肩膀、下颌等身体部位固定并移动手机，按剧本卡完成指定运镜任务。\n3. 手机落地或画面剧烈晃动判失败，换下一组。\n4. 完成任务用时最短、画面最稳的小组获胜。", "tags": ["分组", "动作"], "min_players": 4, "max_players": 12, "need_props": "手机（或相机）", "word_pool": {}, "scene": "陈哲远下颌线绑镜头秒变『嘟嘟脸』，雷霆运镜逗笑众人；李晨挑战下巴掌镜，郑恺还原布洛芬猛男姿势完成神来之笔的臂咚拍摄"}, {"name": "趾压板演技挑战", "play_style": "words", "rules": "1. 铺好趾压板赛道，选手站上趾压板。\n2. 抽一张表演题卡（如模仿一段影视台词、演一种情绪），在趾压板上坚持完成表演。\n3. 表演中断或跳下趾压板判失败。\n4. 完成最多挑战的选手获胜，其余人接受小惩罚。", "tags": ["动作", "积分"], "min_players": 3, "max_players": 12, "need_props": "趾压板", "word_pool": {"challenges": ["趾压板上念完一段绕口令", "趾压板上表演一段愤怒的台词", "趾压板上坚持金鸡独立10秒"]}, "scene": "『浓的传人』在趾压板上狂飙演技疼到表情失控仍坚持；沙溢传球频频失误被全场指认，越努力自证清白越显得可疑"}, {"name": "风暴撕名牌", "play_style": "werewolf", "rules": "1. 主持人给每人发身份：大部分人拿『好人』，2-3人拿『卧底』，卧底互相认识。\n2. 全员在场地内佩戴名牌活动，通过做任务、找线索推进剧情。\n3. 卧底要秘密完成指定任务不被识破；好人通过观察和讨论推理卧底。\n4. 发现嫌疑人可直接撕其名牌将其淘汰，撕错好人则自己出局。\n5. 卧底完成任务或撑到最后获胜；全部卧底被撕出则好人获胜。", "tags": ["狼人杀", "场地", "动作"], "min_players": 6, "max_players": 20, "need_props": "名牌贴纸", "word_pool": {"hint": "按人数自动配置卧底与好人"}, "scene": "白鹿当卧底一开口『我想当好人』一本正经乱分析；李昀锐撕沙溢名牌时意外粘走其假发片成全场爆笑名场面；孟子义上演极限一拖一力阻机密泄漏"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('奔跑吧', 14, 4, '第4期·泉州嘎赛日情侣特辑', '2026-05-15', '[{"name": "抓鳗鱼", "play_style": "words", "rules": "1. 在大水箱（或充气水池）里放入滑溜的玩具鳗鱼、黄鳝（家庭版可用涂了洗洁精的乒乓球代替）。\n2. 轮流上场，限时60秒从水箱里抓出指定数量的目标物。\n3. 抓的时候只能用手，滑掉不算，掉出的要放回去。\n4. 用时最短或抓得最多的人获胜。", "tags": ["场地", "动作"], "min_players": 3, "max_players": 12, "need_props": "水箱、玩具鳗鱼或乒乓球", "word_pool": {}, "scene": "白鹿离水箱八丈远全程尖叫手不敢伸，倪虹洁一边喊害怕一边快准狠完成任务；郑恺苗苗默契十足被调侃像在水产市场开过店"}, {"name": "攻占声母", "play_style": "words", "rules": "1. 每轮抽一个声母（如 m、zh、x）写在黑板上。\n2. 两队轮流说出带这个声母的词语，可以说熟悉的词，也允许临场加字造词。\n3. 5秒内接不上或重复说过的判负一轮。\n4. 先累计赢下3轮的队伍获胜。", "tags": ["坐玩", "积分"], "min_players": 4, "max_players": 16, "need_props": "无", "word_pool": {"chars": ["m", "zh", "x", "sh", "j", "q", "l", "n", "h", "f"]}, "scene": "沙溢面对神奇物品震惊大喊，白鹿临场加字造词惊呆众人，范丞丞靠『天选』声母成功捡漏"}, {"name": "泥潭障碍接力", "play_style": "words", "rules": "1. 分成两队，在泥地（家庭版可用软垫走廊）设置钻圈、平衡木、轮胎等障碍。\n2. 队员依次接力通过全部障碍，碰到障碍要重来。\n3. 先全员完成的队伍获胜。\n4. 场外队友可以喊战术提示，但不能上手帮忙。", "tags": ["分组", "场地", "动作"], "min_players": 6, "max_players": 16, "need_props": "软垫、轮胎、平衡木（家庭版可用桌椅替代）", "word_pool": {}, "scene": "徐志胜场外排兵布阵一套详细战术，上场后发现全白搭，钻轮胎卡了半天；孟子义慢悠悠一句『你没事吧』把场外的苗苗笑到直不起腰"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('奔跑吧', 14, 6, '第6期·厦门R家族宝箱之战', '2026-05-29', '[{"name": "趾压板定格", "play_style": "words", "rules": "1. 铺好趾压板，两队各派2人一组上台。\n2. 主持人亮出指定造型卡（如『骑马蹲裆』『飞机起飞』），两人合作在趾压板上摆出造型保持5秒拍照。\n3. 造型像、坚持稳的组得分，谁先疼得跳起来即失败。\n4. 积分高的队获胜。", "tags": ["动作", "积分"], "min_players": 4, "max_players": 12, "need_props": "趾压板", "word_pool": {"poses": ["骑马蹲裆", "大鹏展翅", "螃蟹横行", "金鸡独立", "平板支撑击掌"]}, "scene": "白鹿的柔韧度让全场惊叹『很权威了』，李晨一把扛起了鹿鹿；范丞丞追问『第三名怎么没你了』冲上热搜"}, {"name": "拼形识意", "play_style": "char", "rules": "1. 两队轮流玩，一人当拼图手，其余人猜。\n2. 拼图手用磁力几何片（或剪纸片）在板上拼出题目词语的画面，不能写字和说话。\n3. 队友在60秒内猜出词语得1分，猜不出换对方出题。\n4. 先到5分的队伍获胜，输队接受砸锅盖噪声惩罚。", "tags": ["坐玩", "积分"], "min_players": 4, "max_players": 16, "need_props": "磁力几何片或剪好的纸片、白板", "word_pool": {"words": ["东方明珠", "长颈鹿", "火箭发射", "火锅", "放风筝", "自行车"]}, "scene": "张康乐抽象诠释东方明珠屡次被误答，李晨精准还原被夸作品堪比展示画；沙溢被吓得直说要不要先把假发片拿下来"}, {"name": "弹射飞椅", "play_style": "words", "rules": "1. 轮流坐上弹射飞椅（家庭版可改成『答错起立表演』的答题椅）。\n2. 主持人出题，题目里暗藏数字、动作陷阱。\n3. 答错或中了陷阱的人被弹飞（落水/表演），其余人幸存进入下一题。\n4. 坚持到最后的人获胜。", "tags": ["动作", "积分"], "min_players": 3, "max_players": 12, "need_props": "弹射飞椅（水上）；家庭版无需道具", "word_pool": {"traps": ["快速抢答：1+1在什么情况下等于3？", "动作陷阱：主持人说坐下但手往上指", "数字陷阱：连报3个数不能带6"]}, "scene": "李昀锐信心满满接招却喜提本季首个飞椅落水；唐九洲算力惊人快速识破陷阱规律；张萌解锁完美落水姿势被称为飞椅天才，白鹿仗义替薛凯琪落水"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('奔跑吧', 14, 7, '第7期·人体文字大作战', '2026-06-05', '[{"name": "人体文字", "play_style": "char", "rules": "1. 分成两队，每轮主持人给题目词语。\n2. 队员合作用身体在场地里拼出这个词语的汉字造型，可以躺、站、叠。\n3. 对方队在60秒内猜出词语，猜对双方各得1分，拼得最像的额外加1分。\n4. 全部轮次结束后总分高的队获胜。", "tags": ["分组", "动作", "积分"], "min_players": 6, "max_players": 16, "need_props": "无", "word_pool": {"words": ["火焰", "大山", "家庭", "奔跑", "日出", "门"]}, "scene": "组字游戏全员CPU冒烟，丞磊刘雨昕智慧担当全力输出，范丞丞忍不住吐槽，李昀锐破解高难度题目，郑恺直呼需要一个AI"}, {"name": "眼色撕名牌", "play_style": "words", "rules": "1. 每人背后贴名牌，围成一圈坐下或站定。\n2. 主持人喊开始后大家互相瞪眼对视，谁先眨眼或移开视线就被点名上场。\n3. 被点名的人进入场地中央接受车轮战撕名牌，守住名牌可继续，被撕即出局。\n4. 最后留守的人获胜。", "tags": ["场地", "动作"], "min_players": 5, "max_players": 16, "need_props": "名牌贴纸", "word_pool": {}, "scene": "李晨遭『露点危机』被紧急人工打码，范丞丞一对三被张真源起跳反杀，丞磊喜获头彩，白鹿一顿狂舞还是被撕"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('奔跑吧', 14, 10, '第10期·水球大战', '2026-06-26', '[{"name": "水球大战", "play_style": "words", "rules": "1. 分成两队，在划定场地内各自搭一个『堡垒』。\n2. 每人拿软水球攻击对方队员，被直接命中2次的人出局退到场边。\n3. 接住对方水球可以让一名出局队友复活。\n4. 全员出局的一方落败，或限时内堡垒存留人数多的队获胜。", "tags": ["分组", "场地", "动作"], "min_players": 6, "max_players": 20, "need_props": "软水球若干", "word_pool": {}, "scene": "范丞丞攻势有点猛疯狂输出，张真源即兴跳了一段霹雳舞，希林娜依·高用小陀螺式旋转躲避攻击"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('奔跑吧', 14, 11, '第11期·绳采飞扬', '2026-07-03', '[{"name": "跳绳挑战赛", "play_style": "words", "rules": "1. 分成两队，轮流上场跳集体长绳。\n2. 每轮全员必须一起进绳连续跳满规定个数（如10个），中途有人绊绳即本轮失败。\n3. 完成轮数多的队获胜；平局时加赛单人1分钟计数跳。\n4. 失败的队接受集体小惩罚。", "tags": ["分组", "动作", "积分"], "min_players": 6, "max_players": 16, "need_props": "长绳、短绳", "word_pool": {}, "scene": "全员跳到力竭边缘频繁失败心态崩溃，孟子义跳绳『黑洞』上线，李昀锐顺利接球超配合"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('奔跑吧', 14, 12, '第12期·杭州收官战', '2026-07-10', '[{"name": "携手同行", "play_style": "words", "rules": "1. 分成两队，场地内藏有目标诗句（如『欲把西湖比西子』）的散落字卡，分布在多辆车的角落里。\n2. 队员轮流进入场地翻找字卡，但场内有隐藏摄影师，谁被拍到就要罚停10秒。\n3. 集齐诗句全部字卡并按顺序拼出，举手喊『答案正确』即完成。\n4. 用时短的队获胜，被拍次数多的要复盘照片接受围观。", "tags": ["分组", "场地", "动作"], "min_players": 6, "max_players": 16, "need_props": "字卡、隐藏相机（手机）", "word_pool": {"sentences": ["欲把西湖比西子", "淡妆浓抹总相宜", "水光潋滟晴方好"]}, "scene": "白鹿完美运用障眼法，张真源直接没收隐藏相机；李昀锐跌跌撞撞奔向范丞丞，全队用时9分19秒被拍了12张"}, {"name": "藏粉笔", "play_style": "words", "rules": "1. 每队领一支超长粉笔，在场地内自选位置藏匿，并布置迷惑假点。\n2. 限时10分钟，双方可以互相侦察并破坏对方的藏匿点（把粉笔转移走）。\n3. 时间到，藏得最隐蔽、没被找到的队伍获胜。\n4. 全程允许耍小聪明骗人，但禁止直接抢夺对方手里的粉笔。", "tags": ["分组", "场地", "动作"], "min_players": 6, "max_players": 16, "need_props": "超长粉笔（或长条玩具）", "word_pool": {}, "scene": "李昀锐把粉笔当金箍棒挥舞失手摔得粉身碎骨，断成几截整齐排在地上配一脸震惊表情；沙溢为帮范丞丞破坏别人粉笔忙到满头大汗"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('现在就出发', 2, 1, '第1期·昭苏天马之乡', '2024-10-26', '[{"name": "歌词传声筒", "play_style": "song", "rules": "1. 分成两队排成纵列，每轮主持人给第一棒一首歌的歌名。\n2. 第一棒只能用动作比划歌词内容传给下一棒，不能唱出声、不能说话。\n3. 依次传到最后，最后一棒要唱出（或说出）正确的歌名。\n4. 猜对的队得分，传得最离谱的组合接受全场围观嘲笑。", "tags": ["坐玩", "动作", "积分"], "min_players": 6, "max_players": 16, "need_props": "无", "word_pool": {"songs": ["敢问路在何方", "两只老虎", "小苹果", "隐形的翅膀", "童话", "常回家看看"]}, "scene": "猜《敢问路在何方》时宋亚轩完全没理解白敬亭的比划，把『你挑着担』一路传成了『你扛着炮』，全员跑偏笑翻全场"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('现在就出发', 2, 2, '第2期·草原显眼包', '2024-10-27', '[{"name": "舞出我同伴", "play_style": "song", "rules": "1. 全员戴上耳机随机听歌（也可能没放歌），每人用舞蹈动作表达歌曲的关键词或情绪。\n2. 大家在场地里互相观察，找出跳同一首歌的『同伴』并站到一起。\n3. 配对成功的小组得分，全场没放歌还在硬跳的人当场曝光。\n4. 几轮后得分最高的小组获胜。", "tags": ["分组", "动作"], "min_players": 6, "max_players": 14, "need_props": "耳机与播放设备（家庭版一人哼歌也行）", "word_pool": {}, "scene": "宋亚轩用『滑落的眼泪』『破碎的心』『颤抖的手』几个动作和艾伦隔着老远对上暗号同频共振；白敬亭的《登月》一响，狼人宋亚轩瞬间提取歌曲信息现场表演打太极"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('现在就出发', 3, 7, '第7期·古董市集与目击狼人杀', '2025-12-06', '[{"name": "目击狼人杀2.0", "play_style": "werewolf", "rules": "1. 只有一人抽到『狼』身份，其他全是羊，大家围坐闭眼。\n2. 羊轮流获得一次睁眼机会，睁眼期间要完成吃西瓜、集牙签等任务；狼可以随时睁眼。\n3. 狼与羊对视即杀掉该羊（2.0版还可在羊起身执行任务时肢体接触杀羊）；被杀的羊全程保持沉默。\n4. 天亮后大家凭目击和推理投票指认狼人；指对好人获胜，狼活到最后狼获胜。", "tags": ["狼人杀", "坐玩"], "min_players": 6, "max_players": 14, "need_props": "西瓜、牙签（任务道具）", "word_pool": {"hint": "单狼多羊配置，狼全程保持普通坐姿不闭眼"}, "scene": "沈腾强行扒开黄景瑜的眼睛对视杀羊被范丞丞偷看个正着，还倒打一耙报警甩锅；最后杀贾冰时被金晨胡先煦同时目击，沈腾哀嚎『意大利怎么有这么多朝阳群众』"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('王牌对王牌', 8, 1, '第1期·科幻电影面试现场', '2023-10-20', '[{"name": "拟音传声筒", "play_style": "char", "rules": "1. 分成两队排成纵列，第一棒抽一个场景词（如狂风暴雨、怪兽来袭）。\n2. 只用嘴和身边小道具发出拟音表现这个词，传给下一棒看和听。\n3. 依次传到最后，最后一棒大声说出（演出的）场景词。\n4. 猜对的队得分，传歪的名场面全场共享。", "tags": ["坐玩", "积分"], "min_players": 6, "max_players": 14, "need_props": "快餐盒、芹菜等拟音小道具", "word_pool": {"scenes": ["狂风暴雨", "怪兽闯进餐厅", "大火燃烧", "马蹄声由远及近", "下冰雹"]}, "scene": "华晨宇炫口技模拟狂风暴雨惊艳全场，传到沈腾只剩捂嘴咳咳咳，关晓彤吓得脖子都缩了；钟汉良与唐嫣全程记反台词，猜题达人杨迪也一筹莫展"}, {"name": "王牌传声筒", "play_style": "sentence", "rules": "1. 队伍排成一列，第一棒看一句台词或短语。\n2. 只许表演和口型小声传递，每人只能说一遍，后面的人凭理解接力。\n3. 最后一棒公布听到的话，与原句对比。\n4. 传得最离谱的一队接受头顶水桶（或坐等浇水）惩罚。", "tags": ["坐玩"], "min_players": 5, "max_players": 14, "need_props": "水桶（惩罚用）", "word_pool": {"sentences": ["大王叫我来巡山", "无精打采地回家吃饭", "下雨天记得收衣服", "烧烤要趁热吃"]}, "scene": "沈腾把台词传成清一色的『啥』，后面全队跟着全是啥；闫妮把『呲呲呲』传成『七七七』最后连自己都不知道该演什么，游戏结束还在看台本补课"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('王牌对王牌', 8, 5, '第5期·博物馆奇妙日', NULL, '[{"name": "英文版传声筒", "play_style": "sentence", "rules": "1. 队伍排成一列，第一棒看一句英文台词。\n2. 只能口语传递（中文队可以掺中式英语），每人只说一遍。\n3. 依次传到最后一棒，复述听到的句子。\n4. 和原句差得最远的队伍表演才艺谢罪。", "tags": ["坐玩"], "min_players": 5, "max_players": 14, "need_props": "无", "word_pool": {"sentences": ["Nice to meet you, my old friend", "The vase is from the Tang Dynasty", "Long time no see, how are you"]}, "scene": "沈腾以优雅寒暄开局却让外国嘉宾满头问号；被戏称『英语沙漏』的沙溢一顿输出让全场笑到抹泪"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('萌探探探案', 3, 5, '第5期·梦幻联动歌会', NULL, '[{"name": "听歌抢答", "play_style": "song", "rules": "1. 分成小队，主持人放歌曲片段（可用哼唱代替）。\n2. 各队抢答歌名，答对得1分，答错锁脚15秒不能抢。\n3. 可以要求播放前奏提示，但每队全场只有2次机会。\n4. 先到10分的队获胜。", "tags": ["坐玩", "积分"], "min_players": 4, "max_players": 16, "need_props": "播放设备", "word_pool": {"songs": ["爱拼才会赢", "最美的太阳", "逆战", "孤勇者", "朋友", "童话"]}, "scene": "赵丽颖用一口塑料闽南话唱《爱拼才会赢》还打着节拍蹦了几下，虽关键信息全对仍被无情嫌弃『发音不标准』；谢娜把亲老公的《最美的太阳》猜成《逆战》被维嘉当场质疑"}, {"name": "蓝水晶智力对抗", "play_style": "words", "rules": "1. 两队各持同数目的水晶（或筹码），每轮暗中出价1-5个押在桌面。\n2. 同时亮出：出价高的一方赢得本轮并拿走双方押注；出价相同则平局各退回。\n3. 水晶先用完的一方落败，留到最后的队获胜。\n4. 全程斗智斗心态，允许虚张声势和表情管理。", "tags": ["坐玩", "积分"], "min_players": 4, "max_players": 12, "need_props": "筹码或纽扣", "word_pool": {}, "scene": "宁静黄子韬一队全程随性放任一输再输；曾舜晞掏出小黑板一本正经列式子『50-3=47』，聪明界当场炸裂"}]');
INSERT INTO remote_feed(show_name, season, episode_no, title, aired_on, payload) VALUES ('萌探探探案', 3, 11, '第11期·毕业季虎鹤奇闻录', '2023-07-07', '[{"name": "吃货狼人杀", "play_style": "werewolf", "rules": "1. 每轮全体闭眼，主持人悄悄指定一名『吃货』，并把一样食物放到他面前。\n2. 吃货闭眼期间偷偷吃掉食物，其他人睁眼后凭气味、咀嚼声和微表情推理谁是吃货。\n3. 轮流发言指认，得票最多的人被揭穿身份。\n4. 猜对平民得分，吃货蒙混过关则吃货得分，多轮累计定胜负。", "tags": ["狼人杀", "坐玩"], "min_players": 5, "max_players": 14, "need_props": "大蒜等气味明显的食物", "word_pool": {"hint": "食物选气味大、咀嚼声响的，如大蒜、薯片、苹果"}, "scene": "黄子韬指认徐志胜是吃货狼人，直言『他一张嘴就露馅了』并劝说对方自曝；『我都闻到大蒜味了』『我都听见娜扎在嚼了』连环爆笑"}, {"name": "真假故事2.0", "play_style": "bluff", "rules": "1. 每人准备一个校园故事（自己经历的或现编的），其中混有编造的假故事。\n2. 轮流讲述自己的故事，其他人可以追问细节。\n3. 全部讲完后，大家投票找出混在里面的假故事。\n4. 找对一个假故事得1分；假故事骗过所有人则讲述者加倍得分。", "tags": ["坐玩"], "min_players": 5, "max_players": 14, "need_props": "无", "word_pool": {}, "scene": "陈宥维讲『情书被贴上黑板传阅』遭张凌赫灵魂点评；徐志胜一开口讲『被表白墙表白』就被全场笃定是假瓜，伤害性不大侮辱性极强"}]');
